-- =============================================
-- Author:        Monir
-- Create date:   8-26-2019
-- Description:   Create a new center user
-- 
-- Modified by:   Osama Saad
-- Modified date: 9-5-2025
-- Modification:  Added password hashing with salt,
--                return inserted user info for NestJS,
--                added isAdmin flag.
-- =============================================
CREATE PROCEDURE [dbo].[addNewCenterUser]
    @userID         INT,
    @userName       VARCHAR(450),
    @centerID       INT,
    @centerType     INT,
    @userPassword   VARCHAR(50),
    @isAdmin        BIT = 0
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (SELECT 1 FROM dbo.Center_Users WHERE username = @userName)
    BEGIN
        RETURN; -- Return nothing to signal a conflict
    END

    DECLARE @salt UNIQUEIDENTIFIER = NEWID();

    INSERT INTO dbo.Center_Users
        (username, user_password, password_salt, center_id, center_user_id, center_type, is_admin)
    VALUES
        (@userName, dbo.getHashedPassword(@userPassword, @salt), @salt, @centerID, @userID, @centerType, @isAdmin);

    -- Return the new user's data so NestJS can use it
    SELECT
        SCOPE_IDENTITY() as ID,
        @userName as username,
        @isAdmin as is_admin;
END
